import{c as t,S as a,j as o,m as r}from"./chunks/framework.C68YPdek.js";const g=JSON.parse('{"title":"Frontend","description":"","frontmatter":{},"headers":[],"relativePath":"developer/architecture/frontend.md","filePath":"developer/architecture/frontend.md"}'),n={name:"developer/architecture/frontend.md"};function s(d,e,i,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to “Frontend”">​</a></h1><p><a href="https://github.com/source-academy/frontend" target="_blank" rel="noreferrer"><code>frontend</code></a> is the web application that learners and staff use: React, Redux with sagas, and Blueprint for the interface. Checked against the repository&#39;s README and source layout on 28 November 2026.</p><h2 id="what-it-contains" tabindex="-1">What it contains <a class="header-anchor" href="#what-it-contains" aria-label="Permalink to “What it contains”">​</a></h2><ul><li><strong>Workspaces</strong>: the Playground (write and run programs), the assessment workspaces (missions, quests and contests), and the grading and editing workspaces for staff. The source is under <code>src/commons</code> (parts shared by the workspaces: editor, REPL, side content, control bar) and <code>src/features</code> (one folder per feature: <code>playground</code>, <code>assessments</code>, <code>grading</code>, <code>adminPanel</code>, <code>game</code>, <code>leaderboard</code>, <code>ragChat</code>, <code>github</code>, <code>persistence</code>, <code>remoteExecution</code>, ...).</li><li><strong>Side-content tabs</strong>: the panels next to the editor (the stepper, visualizers, the documentation tab, and so on). Tools that show a run are plugins that contribute a tab; see <a href="./plugins-and-modules">Plugins and modules</a>.</li><li><strong>Language selection</strong>: the choice of a language and of an evaluator for it comes from the <a href="./directories">language directory</a>. The code is in <code>src/features/directory</code>.</li><li><strong>Running a program</strong>: <code>src/features/conductor</code> creates a <a href="./conductor">Conductor</a> host: it starts the evaluator in a Web Worker (<code>createConductor.ts</code>, <code>BrowserHostPlugin.ts</code>), answers its requests for files and for plugins to load, and loads modules.</li><li><strong>Two builds</strong>: the full build, with the Academy features (login, assessments), and a playground-only build, which is the one deployed to GitHub Pages (see <a href="./deployment">Deployment</a>).</li></ul><h2 id="settings-that-point-to-the-other-parts" tabindex="-1">Settings that point to the other parts <a class="header-anchor" href="#settings-that-point-to-the-other-parts" aria-label="Permalink to “Settings that point to the other parts”">​</a></h2><p>The directories that the frontend reads are feature flags (Settings, then Feature Flags): <code>directory.language.url</code>, <code>directory.plugin.url</code> and <code>directory.modules.url</code>. A deployment can pin them with the <code>REACT_APP_*_DIRECTORY_URL</code> variables in <code>.env</code>, so that they are the same for every user. The backend&#39;s address is also configuration, not code.</p><h2 id="what-it-is-meant-not-to-know" tabindex="-1">What it is meant not to know <a class="header-anchor" href="#what-it-is-meant-not-to-know" aria-label="Permalink to “What it is meant not to know”">​</a></h2><p>The frontend is being arranged so that it knows no tool and no language (see <a href="https://github.com/source-academy/frontend/issues/4587" target="_blank" rel="noreferrer">frontend#4587</a>): the built-in CSE machine is already removed (it is a plugin), and the per-run settings are served under a neutral name. Where the code still names a language or a tool, that is a leftover.</p><h2 id="where-to-read-more" tabindex="-1">Where to read more <a class="header-anchor" href="#where-to-read-more" aria-label="Permalink to “Where to read more”">​</a></h2><p>The repository&#39;s README (setup, environment variables, the Knip dead-code check) and its <a href="https://github.com/source-academy/frontend/wiki" target="_blank" rel="noreferrer">wiki</a>.</p>',10)])])}const p=t(n,[["render",s]]);export{g as __pageData,p as default};
